  EH.iconKeys = Object.keys(P);
  EH.hasIcon = function (n) { return !!P[n]; };
  EH.icon = function (name, cls) {
    var nodes = P[name];
    if (!nodes) { return ''; }
    var body = nodes.map(function (n) {
      var a = n[1], s = '';
      for (var k in a) { s += ' ' + k + '="' + a[k] + '"'; }
      return '<' + n[0] + s + '/>';
    }).join('');
    return '<svg class="ic' + (cls ? ' ' + cls : '') + '" viewBox="0 0 24 24" width="24" height="24"'
      + ' fill="none" aria-hidden="true" focusable="false">' + body + '</svg>';
  };
